                new UNOPSInteraction
                {
                    Type = InteractionType.Call,
                    Date = DateTime.UtcNow,
                    Subject = "including:Strengthening the Electricity Supply System: This project aims to improve living conditions and address interrupted critical and essential services for the most affected Palestinians in Gaza by reconstructing and strengthening the electricity supply system with renewable energy. This aligns with Sweden's commitment to promoting sustainable development and improving living conditions in Gaza.Safe Rubble Removal and Recycling: This project focuses on clearing away war debris",
                    Description = "a critical prerequisite for early recovery and reconstruction interventions\nAsbjørn\n--",
