                    Description = "\"To: Agnes.Annells@fcdo.gov.uk\nCC: Sally.Clifford@fcdo.gov.uk; naimoh@unops.org\nBCC:\nAttachment: --none--\nSubject: Potential projects in Gaza\nBody:",
